'use strict';
// Extend existing saves without replacing the child's character or progress.
function upgradeSave(){data.grade??='';data.birthYear??='';data.bosses??=[];data.customAchievements??=[];data.gifts??=[];data.activity??=[];data.quests.forEach(q=>{q.mode??='paper';q.questions??=[];q.attempts??=[];q.status??=q.done?'done':'active';});}
upgradeSave();
const oldPersist=persist;persist=function(){upgradeSave();oldPersist();};
let adminTab='overview';let questionDraft=[];let exerciseSession=null;
const baseGo=go;go=function(p){if(p==='room'&&sessionRole==='child'&&(!data.grade||!data.birthYear))p='select';baseGo(p)};
login=function(){return `<main class="screen rpg-login">${backdrop()}<header class="topbar">${brand()}<button class="nav-pill" data-action="landing">${icon('home')} 返回開場</button></header><section class="gate-wrap"><div class="gate-heading"><p class="section-kicker">THE GATE OF STARLIGHT</p><div class="gate-ornament">✦</div><h1>選擇你的冒險身份</h1><p>故事之門已開啟。誰將踏上今日的旅程？</p></div><div class="identity-menu" role="group" aria-label="登入身份"><button class="identity-card ${role==='child'?'active':''}" data-role="child" aria-pressed="${role==='child'}"><span class="identity-pointer">◆</span><div class="identity-art child-art">${portrait(data.hero??0)}</div><div class="identity-title"><small>THE ADVENTURER</small><h2>小小冒險者</h2><p>Children Login · 小朋友登入</p></div><span class="identity-flavour">帶住勇氣，收集屬於你的星光。</span><span class="identity-bottom">${icon('star')} 勇氣 · 好奇 · 成長</span></button><button class="identity-card ${role==='parent'?'active':''}" data-role="parent" aria-pressed="${role==='parent'}"><span class="identity-pointer">◆</span><div class="identity-art guild-crest">${icon('shield')}<span>✦</span></div><div class="identity-title"><small>THE GUILD MASTER</small><h2>星光公會長</h2><p>Parents Login · 家長登入</p></div><span class="identity-flavour">為每一份努力，點亮前方的路。</span><span class="identity-bottom">${icon('scroll')} 任務 · 守護 · 陪伴</span></button></div><div class="gate-command"><div class="gate-command-heading">${icon(role==='child'?'star':'shield')}<span>${role==='child'?'冒險者，請出示你的通行印記。':'公會長，請出示你的守護印記。'}</span></div><form id="login-form"><div class="gate-fields"><label for="username"><span>冒險者帳戶</span><input id="username" name="username" autocomplete="username" placeholder="${role==='child'?'test':'admin'}" required></label><span class="gate-divider">✧</span><label for="password"><span>通行密語</span><input id="password" name="password" type="password" autocomplete="current-password" placeholder="輸入密碼" required></label><button class="primary gold" type="submit">${role==='child'?'進入冒險小屋':'進入公會管理室'} ${icon('arrow')}</button></div><p class="error" id="login-error" role="alert"></p></form><p class="gate-demo">測試印記：${role==='child'?'test / test':'admin / admin'} · 進度保留於此瀏覽器</p></div></section><footer class="gate-footer">每一位勇者背後，都有一位溫柔的守護者。</footer></main>`};
const oldCharacterSelect=characterSelect;
characterSelect=function(change=false){const year=Number(today().slice(0,4));return oldCharacterSelect(change).replace('<button class="primary" data-action="confirm-hero">',`<div class="adventurer-profile"><div><label class="field" for="grade">目前年級</label><select class="input" id="grade" required><option value="">選擇年級</option>${[1,2,3,4,5,6].map(n=>`<option value="${n}" ${String(data.grade)===String(n)?'selected':''}>小學${['一','二','三','四','五','六'][n-1]}年級</option>`).join('')}</select></div><div><label class="field" for="birth-year">出生年份</label><select class="input" id="birth-year" required><option value="">選擇出生年份</option>${Array.from({length:26},(_,i)=>year-i).map(y=>`<option value="${y}" ${Number(data.birthYear)===y?'selected':''}>${y} 年</option>`).join('')}</select></div></div><p class="error" id="profile-error" role="alert"></p><button class="primary" data-action="confirm-hero">`)};
const oldRoom=room;
room=function(){return oldRoom().replace('<button class="hotspot h-door" data-action="quests">',`<button class="hotspot h-boss" data-feature="bosses">${icon('shield')} 試煉 Boss <span class="badge">${data.bosses.filter(b=>!b.defeated).length}</span></button><button class="hotspot h-gifts" data-feature="gifts">${icon('sparkle')} 驚喜信箱 ${data.gifts.some(g=>!g.claimed)?'<span class="badge">!</span>':''}</button><button class="hotspot h-door" data-action="quests">`)};
function logActivity(type,title,detail=''){data.activity.unshift({id:crypto.randomUUID(),type,title,detail,at:new Date().toISOString()});data.activity=data.activity.slice(0,250)}
function localTime(v){return new Intl.DateTimeFormat('zh-HK',{timeZone:'Asia/Hong_Kong',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v))}
function progressValue(rule){return rule==='xp'?data.xp:rule==='minutes'?data.totalMinutes:data.quests.filter(q=>q.done).length}
function achievementReady(a){return a.rule==='manual'?!!a.granted:progressValue(a.rule)>=a.target}
function awardQuest(q,minutes=0){if(q.done)return false;q.done=true;q.status='done';q.completedAt=new Date().toISOString();q.help=false;data.xp+=q.xp;data.crystals+=Math.round(q.xp/2);data.totalMinutes+=Math.max(0,minutes);logActivity('complete',q.title,`完成任務 · +${q.xp} EXP`);return true}
function gameTag(q){return q.mode==='screen'?'螢幕練習':'紙本／專注'}
function questRows(parent=false,quests=data.quests){return quests.length?quests.map(q=>`<div class="quest-row ${q.done?'completed':''}"><span class="quest-symbol">${icon(q.done?'check':q.mode==='screen'?'book':'scroll')}</span><div class="quest-text"><h3>${esc(q.title)} <span class="mode-tag">${gameTag(q)}</span></h3><p>${esc(q.detail)}<br>${q.minutes} 分鐘 · +${q.xp} EXP · ${esc(q.date)}</p>${q.help?'<p class="needs-help">需要家長幫手重溫</p>':''}${q.status==='review'?'<p class="needs-help">已交卷，等待家長批改</p>':''}${q.score!==undefined?`<p>最近作答：${q.score} / ${q.questions.length} 題答啱</p>`:''}</div>${parent?`<button class="ghost small-btn" data-review="${q.id}">${q.status==='review'?'批改':'詳情'}</button>${!q.done?`<button class="icon-delete" data-delete="${q.id}" aria-label="移除${esc(q.title)}">×</button>`:''}`:q.done?'<span class="checkmark">已完成</span>':q.status==='review'?'<span class="mode-tag">待批改</span>':`<button class="primary small-btn" data-quest="${q.id}">出發 ${icon('arrow')}</button>`}</div>`).join(''):'<p class="empty">任務板暫時空白，等公會長派發新任務。</p>'}
function dashboardNav(){const tabs=[['overview','sun','成長總覽'],['missions','scroll','任務工房'],['bosses','shield','Boss 試煉'],['achievements','trophy','成就工房'],['gifts','sparkle','驚喜禮物'],['goals','star','目標及成績'],['controls','shield','成長設定'],['ai','sparkle','AI 出題設定']];return tabs.map(([id,i,label])=>`<button class="guild-nav-btn ${adminTab===id?'active':''}" data-admin-tab="${id}">${icon(i)} ${label}${id==='missions'&&data.quests.some(q=>q.status==='review')?'<span class="nav-dot"></span>':''}</button>`).join('')}
admin=function(){return `<main class="guild-screen"><header class="topbar">${brand()}<span class="guild-header-label">GUILD MASTER'S QUARTERS</span><button class="nav-pill" data-action="logout">${icon('logout')} 登出</button></header><div class="guild-layout"><aside class="guild-sidebar"><div class="guild-seal">${icon('shield')}<span>星光公會</span><small>守護每一段成長</small></div><nav aria-label="家長功能">${dashboardNav()}</nav><div class="guild-child">${portrait(data.hero??0,'mini-portrait')}<div><strong>${esc(data.nickname)}</strong><small>${data.grade?`小${data.grade} · `:''}Lv.${level()} · ${data.xp} EXP</small></div></div></aside><div class="guild-content">${({overview:overviewPanel,missions:missionPanel,bosses:parentBossPanel,achievements:parentAchievementPanel,gifts:parentGiftPanel,goals:parentGoalsPanel,controls:controlsPanel,ai:aiSettingsPanel}[adminTab])()}<p class="guild-local-note">私人本機測試 · 同一瀏覽器共用進度 · 尚未連接雲端</p></div></div></main>`};
function panelHeading(en,title,desc){return `<div class="guild-page-heading"><p class="section-kicker">${en}</p><h1>${title}</h1><p class="subtle">${desc}</p></div>`}
function overviewPanel(){const done=data.quests.filter(q=>q.done).length,pending=data.quests.filter(q=>q.status==='review').length;return `${panelHeading('EVERY LITTLE STEP COUNTS','每一步成長，都睇得見。','任務完成、作答情況、需要幫手嘅地方，一眼掌握。')}<div class="guild-stats">${[[done,'已完成任務','scroll'],[data.totalMinutes,'累積專注分鐘','clock'],[data.xp,'累積經驗值','star'],[pending,'等待批改','book']].map(([n,label,i])=>`<div>${icon(i)}<strong>${n}</strong><small>${label}</small></div>`).join('')}</div><div class="guild-grid"><section class="paper admin-panel"><div class="panel-title"><h2>冒險者近況</h2><span class="mode-tag">Lv.${level()}</span></div><div class="child-summary">${portrait(data.hero??0)}<div><h3>${esc(data.nickname)}</h3><p class="subtle">${data.hero===null?'尚未建立角色':heroes[data.hero].name}<br>${data.grade?`小學${data.grade}年級`:'尚未填寫年級'} · ${data.birthYear?`${data.birthYear} 年出生`:'尚未填寫出生年份'}</p><p class="subtle">下一級：${data.xpPerLevel-data.xp%data.xpPerLevel} EXP</p><div class="xpbar large"><span style="width:${(data.xp%data.xpPerLevel)/data.xpPerLevel*100}%"></span></div></div></div><h3 class="small-heading">各科任務進度</h3>${['中文','英文','數學','常識','閱讀','其他'].filter(s=>data.quests.some(q=>q.subject===s)).map(s=>{const qs=data.quests.filter(q=>q.subject===s),n=qs.filter(q=>q.done).length;return `<div class="subject-progress"><span>${s}</span><div class="xpbar"><span style="width:${n/qs.length*100}%"></span></div><small>${n} / ${qs.length}</small></div>`}).join('')}</section><section class="paper admin-panel"><div class="panel-title"><h2>最近活動</h2>${icon('clock')}</div>${data.activity.length?data.activity.slice(0,7).map(a=>`<div class="activity-entry"><span>${icon(a.type==='complete'?'check':a.type==='gift'?'sparkle':'book')}</span><div><strong>${esc(a.title)}</strong><p>${esc(a.detail)}</p><small>${localTime(a.at)}</small></div></div>`).join(''):'<p class="empty">新嘅故事等緊開始。<br>派一個任務，記錄第一步成長。</p>'}</section></div>${data.quests.some(q=>q.help||q.status==='review')?`<section class="paper admin-panel attention-panel"><h2>需要你關注</h2>${data.quests.filter(q=>q.help||q.status==='review').map(q=>`<div class="quest-row"><div class="quest-text"><h3>${esc(q.title)}</h3><p>${q.status==='review'?'練習已交卷，等待你批改。':'小朋友表示有唔明嘅地方。'}</p></div><button class="primary small-btn" data-review="${q.id}">查看</button></div>`).join('')}</section>`:''}`}
function missionPanel(){return `${panelHeading('THE QUEST WORKSHOP','將學習，寫成一場冒險。','紙本練習可以只設計時；螢幕練習可以加入選擇題或文字作答。')}<div class="guild-grid mission-grid"><section class="paper admin-panel"><h2>派發新任務</h2><form id="mission-form"><label class="field" for="mission-title">任務名稱</label><input class="input" id="mission-title" name="title" maxlength="60" placeholder="例如：解開森林文字結界" required><label class="field" for="mission-detail">學習內容／指示</label><textarea class="input" id="mission-detail" name="detail" rows="2" maxlength="1000" placeholder="例如：完成中文工作紙第一頁" required></textarea><label class="field" for="mission-mode">完成方式</label><select class="input" id="mission-mode" name="mode"><option value="paper">紙本練習／專注計時</option><option value="screen">螢幕作答練習</option></select><div class="form-grid"><div><label class="field" for="mission-subject">科目</label><select class="input" id="mission-subject" name="subject">${['中文','英文','數學','常識','閱讀','其他'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label class="field" for="mission-minutes">${'預計時間（分鐘）'}</label><input class="input" id="mission-minutes" name="minutes" type="number" min="1" max="180" value="15" required></div><div><label class="field" for="mission-date">目標日期</label><input class="input" id="mission-date" name="date" type="date" value="${today()}" required></div><div><label class="field" for="mission-xp">經驗值獎勵</label><input class="input" id="mission-xp" name="xp" type="number" min="1" max="1000" value="30" required></div></div><div id="question-builder" hidden><div class="builder-heading"><h3>練習題目</h3><button class="ghost small-btn" type="button" data-feature="add-question">＋ 加入題目</button></div><div id="question-drafts"></div><p class="subtle">文字題可以留空參考答案，交卷後由家長批改。有參考答案嘅題目會自動核對。</p></div><p class="error" id="mission-error" role="alert"></p><div class="form-end"><button class="primary" type="submit">${icon('scroll')} 派發任務</button></div></form></section><section class="paper admin-panel"><h2>全部任務 · ${data.quests.length}</h2>${questRows(true)}</section></div>`}
function questionEditor(q,i){return `<fieldset class="question-draft" data-question-index="${i}"><legend>第 ${i+1} 題</legend><button class="remove-question" type="button" data-remove-question="${i}" aria-label="移除第${i+1}題">×</button><label class="field" for="question-${i}">題目內容</label><textarea class="input" id="question-${i}" data-q="prompt" maxlength="2000" required>${esc(q.prompt||'')}</textarea><label class="field" for="question-type-${i}">題型</label><select class="input" id="question-type-${i}" data-q="type"><option value="text" ${q.type==='text'?'selected':''}>文字作答</option><option value="choice" ${q.type==='choice'?'selected':''}>單項選擇</option></select>${q.type==='choice'?`<label class="field" for="options-${i}">選項（每行一個，最少兩個）</label><textarea class="input" id="options-${i}" data-q="options" rows="3" required>${esc((q.options||[]).join('\n'))}</textarea><label class="field" for="answer-${i}">正確答案（填選項序號，例如 2）</label><input class="input" id="answer-${i}" data-q="answer" type="number" min="1" max="10" value="${esc(q.answer||'')}" required>`:`<label class="field" for="answer-${i}">參考答案（選填，多個可接受答案用 | 分隔）</label><input class="input" id="answer-${i}" data-q="answer" maxlength="500" value="${esc(q.answer||'')}" placeholder="留空由家長批改">`}</fieldset>`}
function readQuestionDrafts(){document.querySelectorAll('.question-draft').forEach(el=>{const i=Number(el.dataset.questionIndex);const explanation=questionDraft[i]?.explanation||'';const get=k=>el.querySelector(`[data-q="${k}"]`)?.value||'';questionDraft[i]={explanation,type:get('type'),prompt:get('prompt'),options:get('options').split('\n').map(s=>s.trim()).filter(Boolean),answer:get('answer')}})}
function drawQuestionDrafts(){const el=$('#question-drafts');if(el){el.innerHTML=questionDraft.map(questionEditor).join('');el.querySelectorAll('fieldset').forEach(f=>f.disabled=$('#question-builder').hidden)}}
function parentBossPanel(){return `${panelHeading('GREAT TRIALS AHEAD','每一場考試，都係一場成長試煉。','設定累積 EXP 準備門檻；經驗值會一直保留。達標後可挑戰，由家長確認完成。')}<div class="guild-grid"><section class="paper admin-panel"><h2>召喚考試 Boss</h2><form id="boss-form"><label class="field" for="boss-name">Boss／考試名稱</label><input class="input" id="boss-name" name="name" placeholder="例如：英文期中考 · 遠古巨龍" maxlength="80" required><label class="field" for="boss-description">準備目標</label><textarea class="input" id="boss-description" name="description" placeholder="重溫 Unit 1–3，完成所有錯題改正" maxlength="1000" required></textarea><div class="form-grid"><div><label class="field" for="boss-date">考試日期</label><input class="input" id="boss-date" type="date" name="date" value="${today()}" required></div><div><label class="field" for="boss-threshold">所需累積 EXP</label><input class="input" id="boss-threshold" name="threshold" type="number" min="1" max="1000000" value="300" required></div><div><label class="field" for="boss-reward">擊敗獎勵（水晶）</label><input class="input" id="boss-reward" name="reward" type="number" min="0" max="10000" value="100" required></div></div><div class="form-end"><button class="primary" type="submit">${icon('shield')} 建立 Boss</button></div></form></section><section class="paper admin-panel"><h2>試煉目標</h2>${bossCards(true)}</section></div>`}
function bossCards(parent=false){return data.bosses.length?data.bosses.map(b=>{const ready=data.xp>=b.threshold,percent=Math.min(100,Math.floor(data.xp/b.threshold*100));return `<article class="boss-card ${b.defeated?'defeated':''}"><div class="boss-emblem"><img src="assets/forest-dragon.png" alt="森林守護巨龍"></div><div class="boss-info"><span class="section-kicker">${b.defeated?'TRIAL COMPLETE':ready?'READY TO CHALLENGE':'GREAT TRIAL'}</span><h3>${esc(b.name)}</h3><p>${esc(b.description)}</p><small>${esc(b.date)} · 擊敗獎勵 ${b.reward} 水晶</small><div class="boss-progress"><span style="width:${percent}%"></span></div><p>${data.xp} / ${b.threshold} EXP ${!ready?`· 仲差 ${b.threshold-data.xp} EXP`:'· 準備值已達標'}</p>${b.defeated?'<span class="checkmark">✓ Boss 已擊敗</span>':parent?`<button class="primary small-btn" data-defeat-boss="${b.id}" ${ready?'':'disabled'}>確認已完成考試 · 擊敗 Boss</button>`:`<button class="primary small-btn" data-challenge-boss="${b.id}" ${ready?'':'disabled'}>${b.challenged?'查看挑戰進度':'挑戰 Boss'}</button>`}</div></article>`}).join(''):'<p class="empty">下一位 Boss 仲未現身。<br>家長可以為默書、測驗或考試設定試煉。</p>'}
function parentAchievementPanel(){return `${panelHeading('THE HALL OF HONOURS','為值得記住嘅努力，頒一個徽章。','可以按 EXP、完成任務數或專注分鐘自動解鎖，亦可以由家長親自頒發。')}<div class="guild-grid"><section class="paper admin-panel"><h2>設計成就</h2><form id="achievement-form"><label class="field" for="achievement-name">成就名稱</label><input class="input" id="achievement-name" name="name" maxlength="60" placeholder="例如：錯題小偵探" required><label class="field" for="achievement-description">成就說明</label><textarea class="input" id="achievement-description" name="desc" maxlength="500" required></textarea><label class="field" for="achievement-rule">解鎖條件</label><select class="input" id="achievement-rule" name="rule"><option value="manual">由家長親自頒發</option><option value="quests">完成任務數量</option><option value="minutes">累積專注分鐘</option><option value="xp">累積經驗值 EXP</option></select><label class="field" for="achievement-target">目標數值（手動頒發可略過）</label><input class="input" id="achievement-target" name="target" type="number" min="1" max="1000000" value="5"><label class="field" for="achievement-crystals">獎勵水晶</label><input class="input" id="achievement-crystals" name="crystals" type="number" min="0" max="1000" value="5" required><div class="form-end"><button class="primary" type="submit">${icon('trophy')} 建立成就</button></div></form></section><section class="paper admin-panel"><h2>公會成就</h2>${data.customAchievements.length?data.customAchievements.map(a=>`<div class="custom-achievement">${icon('trophy')}<div><h3>${esc(a.name)}</h3><p>${esc(a.desc)}</p><small>${a.rule==='manual'?'家長頒發':`${{xp:'經驗值',quests:'完成任務',minutes:'專注分鐘'}[a.rule]} ${progressValue(a.rule)} / ${a.target}`} · ${a.crystals} 水晶</small></div>${a.claimed?'<span class="checkmark">已領取</span>':a.rule==='manual'&&!a.granted?`<button class="primary small-btn" data-grant-achievement="${a.id}">頒發</button>`:`<span class="mode-tag">${achievementReady(a)?'已解鎖':'進行中'}</span>`}</div>`).join(''):'<p class="empty">除了原有成就，你亦可以設計專屬徽章。</p>'}</section></div>`}
function parentGiftPanel(){return `${panelHeading('A LITTLE SURPRISE','努力嘅日常，也值得一份驚喜。','禮物會送到小朋友嘅驚喜信箱。實體禮物領取後，仍可追蹤兌換狀態。')}<div class="guild-grid"><section class="paper admin-panel"><h2>寄出特別禮物</h2><form id="gift-form"><label class="field" for="gift-name">禮物名稱</label><input class="input" id="gift-name" name="name" maxlength="60" placeholder="例如：週末雪糕券" required><label class="field" for="gift-message">給小朋友嘅話</label><textarea class="input" id="gift-message" name="message" maxlength="1000" placeholder="爸爸見到你今個星期好努力，好欣賞你！" required></textarea><label class="field" for="gift-kind">禮物種類</label><select class="input" id="gift-kind" name="kind"><option value="real">實體禮物／家庭活動兌換券</option><option value="item">遊戲紀念物</option><option value="currency">水晶獎勵</option></select><div class="form-grid"><div><label class="field" for="gift-crystals">附送水晶</label><input class="input" id="gift-crystals" name="crystals" type="number" min="0" max="1000" value="0" required></div></div><div class="form-end"><button class="primary" type="submit">${icon('sparkle')} 寄出驚喜</button></div></form></section><section class="paper admin-panel"><h2>已寄出嘅禮物</h2>${data.gifts.length?data.gifts.slice().reverse().map(g=>`<div class="gift-list-item">${icon('sparkle')}<div><h3>${esc(g.name)}</h3><p>${esc(g.message)}</p><small>${g.claimed?(g.kind==='real'?(g.fulfilled?'已兌換':'已領取 · 等待家長兌換'):'已領取'):'信箱內 · 未領取'}</small></div>${g.claimed&&g.kind==='real'&&!g.fulfilled?`<button class="ghost small-btn" data-fulfil-gift="${g.id}">標記已兌換</button>`:''}</div>`).join(''):'<p class="empty">一份意想不到嘅鼓勵，會令今日更加特別。</p>'}</section></div>`}
const oldAchievementBody=achievementBody;
achievementBody=function(){return oldAchievementBody().replace(`已解鎖 ${unlockedAchievements()} / ${achievements.length}`,`原有成就 ${oldUnlocked()} / ${achievements.length}`)+`<h3 class="small-heading">公會專屬成就</h3>${data.customAchievements.length?`<div class="achievement-grid">${data.customAchievements.map(a=>`<div class="achievement-item ${achievementReady(a)?'unlocked':'locked'}"><span class="achievement-emblem">${icon('trophy')}</span><h3>${esc(a.name)}</h3><p>${esc(a.desc)}</p><small>${a.claimed?'已領取':achievementReady(a)?'已解鎖':a.rule==='manual'?'等待公會長頒發':`${progressValue(a.rule)} / ${a.target}`}</small>${achievementReady(a)&&!a.claimed?`<button class="primary small-btn" data-claim-achievement="${a.id}">領取 ${a.crystals} 水晶</button>`:''}</div>`).join('')}</div>`:'<p class="subtle">公會長仲未設計新徽章。</p>'}`};
const oldUnlocked=unlockedAchievements;
unlockedAchievements=function(){return oldUnlocked()+data.customAchievements.filter(achievementReady).length};
function giftBody(){return `<p class="subtle">公會長為你送來嘅心意，正等你親手打開。</p>${data.gifts.length?data.gifts.slice().reverse().map(g=>`<article class="child-gift"><span class="gift-illustration">${icon(g.kind==='real'?'chest':'sparkle')}</span><p class="section-kicker">A GIFT FROM YOUR GUILD MASTER</p><h3>${esc(g.name)}</h3><p>${esc(g.message)}</p><small>${g.crystals?`${g.crystals} 水晶` : ''}${g.kind==='real'?' · 家庭禮物兌換券':''}</small><button class="primary" data-claim-gift="${g.id}" ${g.claimed?'disabled':''}>${g.claimed?(g.kind==='real'?(g.fulfilled?'已兌換':'已領取 · 搵家長兌換'):'已領取'):'打開禮物'}</button></article>`).join(''):'<p class="empty">信箱暫時未有新禮物。<br>每一份努力，公會長都睇得見。</p>'}`}
const oldCalendarBody=calendarBody;
calendarBody=function(){return oldCalendarBody()+`<h3 class="small-heading">考試 Boss 日程</h3>${data.bosses.map(b=>`<div class="calendar-event"><strong>${esc(b.date)} · ${esc(b.name)}</strong><p>${b.defeated?'已完成':`${data.xp} / ${b.threshold} EXP 準備值`}</p></div>`).join('')||'<p class="subtle">暫時未有考試 Boss。</p>'}`};
const oldStartQuest=startQuest;
startQuest=function(id){const q=data.quests.find(q=>q.id===id);if(!q||q.done||q.status==='review'||sessionRole!=='child')return;if(q.mode==='screen'){openExercise(q)}else{logActivity('start',q.title,'開始紙本／專注任務');persist();oldStartQuest(id)}};
const oldFinishQuest=finishQuest;
finishQuest=function(mode){if(timer&&elapsed()>=timer.total){const q=data.quests.find(q=>q.id===timer.id);if(mode==='complete'){q.completedAt=new Date().toISOString();q.status='done';logActivity('complete',q.title,`紙本／專注任務完成 · +${q.xp} EXP`)}else logActivity(mode==='help'?'help':'partial',q.title,mode==='help'?'需要家長幫手重溫':'完成一部分，下次繼續')}oldFinishQuest(mode)};
function normalizeAnswer(s){return String(s).normalize('NFKC').trim().toLocaleLowerCase().replace(/\s+/g,' ')}
function evaluateQuestion(q,answer){if(q.type==='choice')return Number(answer)===Number(q.answer);if(!q.answer.trim())return null;return q.answer.split('|').some(s=>normalizeAnswer(s)===normalizeAnswer(answer))}
function openExercise(q){exerciseSession={id:q.id,started:Date.now()};logActivity('start',q.title,'開始螢幕練習');persist();openModal('exercise',`<div class="exercise-banner">${icon('book')}<div><h3>${esc(q.title)}</h3><p>${esc(q.detail)}</p><small>預計 ${q.minutes} 分鐘 · +${q.xp} EXP · 可以慢慢作答</small></div></div><form id="exercise-form" data-id="${q.id}">${q.questions.map((question,i)=>`<fieldset class="exercise-question"><legend>第 ${i+1} 題</legend><p>${esc(question.prompt).replace(/\n/g,'<br>')}</p>${question.type==='choice'?question.options.map((o,j)=>`<label class="answer-option"><input type="radio" name="answer-${i}" value="${j+1}" required ${q.draftAnswers?.[i]===String(j+1)?'checked':''}><span class="answer-letter">${String.fromCharCode(65+j)}</span><span>${esc(o)}</span></label>`).join(''):`<label class="field" for="exercise-answer-${i}">你的答案</label><textarea class="input" id="exercise-answer-${i}" name="answer-${i}" rows="2" maxlength="2000" required>${esc(q.draftAnswers?.[i]||'')}</textarea>`}</fieldset>`).join('')}<div class="inline-actions"><button class="ghost" type="button" data-save-exercise="${q.id}">儲存，稍後繼續</button><button class="primary" type="submit">交卷 ${icon('arrow')}</button></div></form>`,'知識試煉')}
function saveExercise(){if(!exerciseSession)return;const q=data.quests.find(q=>q.id===exerciseSession.id);if(!q)return;const f=$('#exercise-form');if(f){const values=new FormData(f);q.draftAnswers=q.questions.map((_,i)=>String(values.get(`answer-${i}`)||''));q.exerciseSeconds=(q.exerciseSeconds||0)+(Date.now()-exerciseSession.started)/1000;exerciseSession=null;persist()}}
const oldCloseModal=closeModal;
closeModal=function(){if(modal==='exercise'&&exerciseSession){saveExercise();notify('答案已儲存，下次可以繼續。')}oldCloseModal()};
function submitExercise(form){const q=data.quests.find(q=>q.id===form.dataset.id);if(!q||q.done||q.status==='review')return;const f=new FormData(form),answers=q.questions.map((_,i)=>String(f.get(`answer-${i}`)||'').trim());if(answers.some(a=>!a)){notify('仲有題目未完成，睇多一次先。');return}const results=q.questions.map((question,i)=>evaluateQuestion(question,answers[i]));const secs=(q.exerciseSeconds||0)+(exerciseSession?(Date.now()-exerciseSession.started)/1000:0);const attempt={at:new Date().toISOString(),answers,results,seconds:secs};q.attempts.push(attempt);q.score=results.filter(r=>r===true).length;q.draftAnswers=answers;exerciseSession=null;q.exerciseSeconds=0;data.totalMinutes+=Math.round(secs/60);logActivity('submit',q.title,`交卷 · ${q.score} / ${q.questions.length} 題已自動答啱${results.includes(null)?' · 部分待批改':''}`);const wrong=results.some(r=>r===false),needsReview=results.includes(null);if(needsReview){q.status='review';persist();render();openModal('result',`<div class="result-emblem">${icon('book')}</div><h3 class="result-title">試煉之書已送到公會長手上。</h3><p class="empty">你嘅答案已交俾家長批改，<br>確認完成後就會收到任務獎勵。</p><button class="primary" data-action="close">返屋企</button>`,'交卷完成')}else if(!wrong){awardQuest(q,0);persist();render();show('treasure');notify(`練習完成！+${q.xp} EXP，獲得一個寶箱。`)}else{q.status='active';q.help=true;persist();openModal('result',`<h3 class="result-title">你已答啱 ${q.score} / ${q.questions.length} 題。</h3><p class="subtle">答錯係發現新線索嘅開始，重溫後可以再試。</p>${q.questions.map((question,i)=>`<div class="review-answer"><strong>第 ${i+1} 題 · ${results[i]?'✓ 答啱':'需要重溫'}</strong><p>${esc(question.prompt)}</p><small>你的答案：${esc(question.type==='choice'?question.options[Number(answers[i])-1]:answers[i])}</small></div>`).join('')}<button class="primary" data-retry-exercise="${q.id}">重新挑戰</button>`,'試煉回顧')}}
function reviewQuest(id){
 const q=data.quests.find(q=>q.id===id);if(!q)return;
 const a=q.attempts.at(-1);
 let body=`<div class="exercise-banner">${icon('scroll')}<div><h3>${esc(q.title)}</h3><p>${esc(q.detail)}</p><small>${gameTag(q)} · ${q.minutes} 分鐘 · +${q.xp} EXP</small></div></div>`;
 if(a){body+=`<p class="subtle">最近交卷：${localTime(a.at)}</p>`;
  body+=q.questions.map((question,i)=>{
   const submitted=question.type==='choice'?(question.options[Number(a.answers[i])-1]||'未作答'):a.answers[i];
   const reference=question.type==='choice'?(question.options[Number(question.answer)-1]||''):question.answer;
   return `<div class="review-answer"><strong>第 ${i+1} 題 · ${a.results[i]===null?'待家長批改':a.results[i]?'自動核對：答啱':'自動核對：需重溫'}</strong><p>${esc(question.prompt)}</p><div class="submitted-answer">${esc(submitted)}</div><small>${question.answer?'參考答案：'+esc(reference):'未設定參考答案，由家長批改。'}</small></div>`;
  }).join('');
 }else if(q.mode==='screen'){
  body+=`<p class="subtle">尚未交卷 · ${q.questions.length} 題</p>`+q.questions.map((v,i)=>`<div class="review-answer"><strong>第 ${i+1} 題</strong><p>${esc(v.prompt)}</p></div>`).join('');
 }else{body+=`<p class="empty">紙本／專注任務，完成計時後由小朋友回報。${q.done?'已完成。':'尚未完成。'}</p>`;}
 if(q.status==='review')body+=`<div class="inline-actions"><button class="ghost" data-return-exercise="${q.id}">退回重溫</button><button class="primary" data-approve-exercise="${q.id}">確認完成及發獎勵</button></div>`;
 openModal('parent-review',body,'任務及作答記錄');
}
// Handle new controls before the original app's generic button handler.
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='confirm-hero'){const grade=$('#grade')?.value,birth=$('#birth-year')?.value;if(!grade||!birth){e.stopImmediatePropagation();$('#profile-error').textContent='請先選擇目前年級同出生年份。';(!grade?$('#grade'):$('#birth-year'))?.focus();return}data.grade=Number(grade);data.birthYear=Number(birth)}if(b.dataset.adminTab){if(sessionRole!=='parent')return;questionDraft=[];adminTab=b.dataset.adminTab;render();return}if(b.dataset.feature==='add-question'){readQuestionDrafts();if(questionDraft.length>=20){notify('每個任務最多可以加入 20 題。');return}questionDraft.push({type:'text',prompt:'',answer:'',options:[]});drawQuestionDrafts();return}if(b.dataset.removeQuestion!==undefined){readQuestionDrafts();questionDraft.splice(Number(b.dataset.removeQuestion),1);drawQuestionDrafts();return}if(b.dataset.feature==='bosses'&&sessionRole==='child'){lastFocus=b;openModal('bosses',`<p class="subtle">完成任務累積 EXP，為大試煉做好準備。EXP 唔會因挑戰而扣減。</p>${bossCards()}`,'考試 Boss 試煉');return}if(b.dataset.feature==='gifts'&&sessionRole==='child'){lastFocus=b;openModal('gifts',giftBody(),'驚喜信箱');return}if(b.dataset.review&&sessionRole==='parent'){reviewQuest(b.dataset.review);return}if(b.dataset.saveExercise&&sessionRole==='child'){saveExercise();closeModal();notify('答案已儲存，下次繼續。');return}if(b.dataset.retryExercise&&sessionRole==='child'){const q=data.quests.find(q=>q.id===b.dataset.retryExercise);if(q&&!q.done)openExercise(q);return}if(b.dataset.approveExercise&&sessionRole==='parent'){const q=data.quests.find(q=>q.id===b.dataset.approveExercise);if(q?.status==='review'){if(typeof readReviewScore==='function'&&!readReviewScore(q))return;const a=q.attempts.at(-1);awardQuest(q,0);persist();render();notify('已確認完成，經驗值同寶箱獎勵已發放。')}return}if(b.dataset.returnExercise&&sessionRole==='parent'){const q=data.quests.find(q=>q.id===b.dataset.returnExercise);if(q?.status==='review'){q.status='active';q.help=true;logActivity('review',q.title,'家長建議重溫後再試');persist();render();notify('練習已退回，小朋友可以重新作答。')}return}if(b.dataset.challengeBoss&&sessionRole==='child'){const boss=data.bosses.find(v=>v.id===b.dataset.challengeBoss);if(boss&&!boss.defeated&&(typeof bossEligible==='function'?bossEligible(boss):data.xp>=boss.threshold)){boss.challenged=true;logActivity('boss',boss.name,'EXP 準備達標，已向考試 Boss 發出挑戰');persist();openModal('boss-challenge',`<div class="boss-challenge-symbol"><img src="assets/forest-dragon.png" alt="森林守護巨龍"></div><h3 class="result-title">${esc(boss.name)}</h3><p class="empty">${data.xp} EXP · 你嘅準備力量已經達標！<br>完成測驗或考試後，由公會長確認擊敗 Boss。</p><button class="primary" data-action="close">準備迎戰 ${icon('star')}</button>`,'試煉之門已開啟')}return}if(b.dataset.defeatBoss&&sessionRole==='parent'){const boss=data.bosses.find(v=>v.id===b.dataset.defeatBoss);if(boss&&!boss.defeated&&(typeof bossEligible==='function'?bossEligible(boss):data.xp>=boss.threshold)){if(typeof openBossResult==='function'){openBossResult(boss);return}boss.defeated=true;data.crystals+=boss.reward;persist();render()}return}if(b.dataset.grantAchievement&&sessionRole==='parent'){const a=data.customAchievements.find(v=>v.id===b.dataset.grantAchievement);if(a&&a.rule==='manual'&&!a.granted){a.granted=true;logActivity('achievement',a.name,'公會長頒發咗一個專屬成就');persist();render();notify('成就已送到小朋友嘅成就手冊。')}return}if(b.dataset.claimAchievement&&sessionRole==='child'){const a=data.customAchievements.find(v=>v.id===b.dataset.claimAchievement);if(a&&achievementReady(a)&&!a.claimed){a.claimed=true;data.crystals+=a.crystals;logActivity('achievement',a.name,`領取成就 · +${a.crystals} 水晶`);persist();render();show('achievements');notify('專屬成就獎勵已領取！')}return}if(b.dataset.claimGift&&sessionRole==='child'){const g=data.gifts.find(v=>v.id===b.dataset.claimGift);if(g&&!g.claimed){g.claimed=true;g.claimedAt=new Date().toISOString();data.crystals+=g.crystals;if(g.kind==='item')data.treasures.push({name:g.name,desc:g.message});logActivity('gift',g.name,'打開咗公會長送來嘅驚喜禮物');persist();render();openModal('gifts',giftBody(),'驚喜信箱');notify('禮物已打開！'+(g.kind==='real'?'記得搵家長兌換。':''))}return}if(b.dataset.fulfilGift&&sessionRole==='parent'){const g=data.gifts.find(v=>v.id===b.dataset.fulfilGift);if(g?.claimed&&g.kind==='real'&&!g.fulfilled){g.fulfilled=true;logActivity('gift',g.name,'家長確認實體禮物已兌換');persist();render();notify('已記錄禮物兌換。')}return}},true);
document.addEventListener('change',e=>{if(e.target.id==='mission-mode'){const screen=e.target.value==='screen';$('#question-builder').hidden=!screen;document.querySelectorAll('.question-draft').forEach(el=>el.disabled=!screen);if(screen&&!questionDraft.length){questionDraft.push({type:'text',prompt:'',answer:'',options:[]});drawQuestionDrafts()}}if(e.target.matches('[data-q="type"]')){readQuestionDrafts();drawQuestionDrafts()}});
function bounded(value,min,max){const n=Number(value);return Number.isFinite(n)&&Number.isInteger(n)&&n>=min&&n<=max?n:null}
document.addEventListener('submit',e=>{const id=e.target.id;if(!['mission-form','boss-form','achievement-form','gift-form','exercise-form'].includes(id))return;e.preventDefault();const f=new FormData(e.target);if(id==='exercise-form'){if(sessionRole==='child')submitExercise(e.target);return}if(sessionRole!=='parent')return;if(id==='mission-form'){readQuestionDrafts();const mode=f.get('mode'),title=f.get('title').trim(),detail=f.get('detail').trim(),minutes=bounded(f.get('minutes'),1,180),xp=bounded(f.get('xp'),1,1000);if(!title||!detail||!minutes||!xp)return;let questions=[];if(mode==='screen'){if(!questionDraft.length){$('#mission-error').textContent='請至少加入一道題目。';return}for(const [i,q] of questionDraft.entries()){if(!q.prompt.trim()){notify(`第 ${i+1} 題仲未填題目。`);return}if(q.type==='choice'&&(q.options.length<2||q.options.length>10||!bounded(q.answer,1,q.options.length))){$('#mission-error').textContent=`第 ${i+1} 題請填 2–10 個選項，同有效嘅正確答案序號。`;return}questions.push({...q,prompt:q.prompt.trim(),answer:q.answer.trim()})}}data.quests.push({id:crypto.randomUUID(),title,detail,mode,minutes,xp,subject:f.get('subject'),date:f.get('date'),done:false,status:'active',questions,attempts:[]});logActivity('assigned',title,`公會長派發${mode==='screen'?`螢幕練習 · ${questions.length} 題`:'紙本／專注任務'}`);questionDraft=[];persist();render();notify('新任務已送到小朋友嘅任務板。')}else if(id==='boss-form'){const threshold=bounded(f.get('threshold'),1,1000000),reward=bounded(f.get('reward'),0,10000);if(!threshold||reward===null)return;data.bosses.push({id:crypto.randomUUID(),name:f.get('name').trim(),description:f.get('description').trim(),date:f.get('date'),threshold,reward,defeated:false});logActivity('boss',f.get('name').trim(),'公會長設定咗一個考試 Boss');persist();render();notify('考試 Boss 已登場。')}else if(id==='achievement-form'){const rule=f.get('rule'),target=rule==='manual'?1:bounded(f.get('target'),1,1000000),crystals=bounded(f.get('crystals'),0,1000);if(!target||crystals===null)return;data.customAchievements.push({id:crypto.randomUUID(),name:f.get('name').trim(),desc:f.get('desc').trim(),rule,target,crystals,granted:false,claimed:false});persist();render();notify('專屬成就已建立。')}else if(id==='gift-form'){const crystals=bounded(f.get('crystals'),0,10000);if(crystals===null)return;data.gifts.push({id:crypto.randomUUID(),name:f.get('name').trim(),message:f.get('message').trim(),kind:f.get('kind'),crystals,claimed:false,fulfilled:false});logActivity('gift',f.get('name').trim(),'公會長寄出咗一份驚喜');persist();render();notify('禮物已寄到小朋友嘅驚喜信箱。')}});
window.addEventListener('beforeunload',()=>{if(exerciseSession)saveExercise()});
render();
